Local Unset Keyed Unification.

Definition fl_pb (a : Z) : Z := sh a + 4095 - (sh a + 4095) mod 2 ^ 12.
Definition fl_pe (a msz : Z) : Z := sh (a + msz) - sh (a + msz) mod 2 ^ 12.

